/**
 * The field codes for each field of a request that failed validation, by the field's JSON name.
 * @nullable
 */
export type ProblemDetailsErrors = null | {[key: string]: FieldErrorCode[]};

export interface ProblemDetails {
  /** @nullable */
  type?: string | null;
  /** @nullable */
  title?: string | null;
  /** @nullable */
  status?: number | null;
  /** @nullable */
  detail?: string | null;
  /** @nullable */
  instance?: string | null;
  code: ErrorCode;
  /**
     * The field codes for each field of a request that failed validation, by the field's JSON name.
     * @nullable
     */
  errors?: ProblemDetailsErrors;
  /** The trace id of the request, for the logs. */
  traceId: string;
  /**
     * The tenants the error is about, when a client needs them to act, such as the tenants a user is the last Owner of.
     * @nullable
     */
  tenantIds?: string[] | null;
  /**
     * The entitlement key the error is about: the feature that is off, or the limit that is reached.
     * @nullable
     */
  entitlement?: string | null;
}

/**
 * The signed-in user's own names, each within the API's limit. The API trims each name before it counts its length. Both are required,
 * so a client that leaves one out never clears it.
 */
export interface RenameMeRequest {
  /** @maxLength 100 */
  firstName: string;
  /** @maxLength 100 */
  lastName: string;
}

/**
 * A tenant's new name. The API trims it before it counts its length. The slug never changes.
 */
export interface RenameTenantRequest {
  /** @maxLength 100 */
  name: string;
}

/**
 * A user's new names, each within the API's limit. The API trims each name before it counts its length.
 */
export interface RenameUserRequest {
  /** @maxLength 100 */
  firstName: string;
  /** @maxLength 100 */
  lastName: string;
}

/**
 * The tenant's value of the key in the route, over its plan's value; its expiry, after now, or null for one that never expires; and the
 * system admin's reason, required. The API trims the reason before it counts its length.
 */
export interface SetEntitlementOverrideRequest {
  value: EntitlementValueRequest;
  /** @nullable */
  expiresAt: string | null;
  /** @maxLength 500 */
  reason: string;
}

/**
 * Why the system admin suspends the tenant, within the API's limit. The API trims the reason before it counts its length. A member
 * never sees it. It holds no personal data, such as a person's name or email address: the platform's audit log keeps it after the
 * tenant's purge (A8).
 */
export interface SuspendTenantRequest {
  /** @maxLength 500 */
  reason: string;
}

