export interface TenantOwnerResponse {
  userId: string;
  /** @nullable */
  firstName: string | null;
  /** @nullable */
  lastName: string | null;
  /** @nullable */
  email: string | null;
}

/**
 * One tenant for the platform's detail screen: as an item of the list, with every Owner, in the order they joined, in place of the
 * first. A closed tenant says until when it can be reopened; a closed tenant, or one whose purge has begun, says when its Owners are, or
 * were, warned of the purge (null otherwise).
 */
export interface TenantDetailResponse {
  id: string;
  name: string;
  slug: string;
  status: TenantResponseStatus;
  createdAt: string;
  /** @nullable */
  suspensionReason: string | null;
  /** @nullable */
  closedAt: string | null;
  /** @nullable */
  purgedAt: string | null;
  /** @nullable */
  reopenableUntil: string | null;
  /** @nullable */
  purgeWarningAt: string | null;
  memberCount: number;
  ownerCount: number;
  owners: TenantOwnerResponse[];
  ownerInvitation: null | OwnerInvitationResponse;
}

/**
 * One key of a tenant's entitlements: whether it is a feature, the plan's value (null when the plan has none: the key is then closed),
 * the tenant's override (null when it has none), the effective value at the moment of the request, and what the tenant has that the key
 * counts (`count`).
 */
export interface TenantEntitlementResponse {
  key: string;
  isFeature: boolean;
  planValue: null | EntitlementValueResponse;
  override: null | EntitlementOverrideResponse;
  effective: EntitlementValueResponse;
  count: number;
}

